//! 🥡️ Typed default placement denies missing copy and empty arrays remain genuine values.
use semio_framework_value_native_default::{NativeDefault,NativeDefaultValue,NativeDefaultCursor,NativeArrayDefaultCursor};
use semio_framework_value_testing_admission::{self as fixture,BankWallet,EffectBank,Wallet,RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,ValueError,OriginalSourceTurnIdentity};
use semio_framework_value_native_decoding::native_decoding::{NativeDecodeControl,OriginalEffectAuthority,OriginalEffectProducer,OriginalEffectReply,OriginalEffectReplyComplete,OriginalReceivingPrimary};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[test]
fn empty_string_default_requires_its_real_option_placement_and_never_allocates(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️work/🥡️placement/🔣️.json")).unwrap();let mut bank=Wallet::from_profile(&law["stock"]);let mut output=None;let mut actual=None;let mut grant=bank.loan(1,4096);grant.maximum_copy_bytes=0;
 let(turn,heap)=observe(||<String as NativeDefaultValue>::admit_default(&mut output,grant,Some(&mut actual)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(output,None);assert_eq!(actual,None);assert_eq!(heap,(0,0));
 let demand=<String as NativeDefaultValue>::default_demand();assert_eq!(demand.copy_bytes,std::mem::size_of::<Option<String>>());assert!(demand.copy_bytes>0);let grant=bank.loan(1,demand.copy_bytes);assert!(<String as NativeDefaultValue>::default_work_demand().unwrap()<=bank.work_remaining());
 let(turn,heap)=observe(||<String as NativeDefaultValue>::admit_default(&mut output,grant,Some(&mut actual)));let p=turn.result.unwrap().progress();bank.post(p,turn.work,grant,heap);assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(actual,None);assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),law["string"]);fixture::close_owned(output.take().unwrap(),&mut bank,4096,10000);
}
type Op<'a>=&'a mut dyn for<'r> FnMut(&mut RetainedAllocationEffect<'_>,OriginalEffectReply<'r,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>;
struct Resident;
impl OriginalEffectProducer for Resident{
 type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'turn,'source>=Op<'turn> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn receive<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{context(effect,reply)}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
fn synchronous(poll:RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("synchronous default action stayed pending")}}
fn through_reply(bank:&mut EffectBank,grant:RetainedCloneGrant,maximum:u64,operation:Op<'_>)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{
 let mut authority=OriginalEffectAuthority::new(Resident);let mut slot=None;let mut reply=None;let mut operation=operation;
 let(poll,_)=bank.run(grant,maximum,|effect|match authority.drive(&mut operation,effect,&mut slot){Ok(true)=>{slot.as_mut().expect("settled action").transfer_reply(&mut reply).expect("empty reply slot");RetainedWorkPoll::Complete(RetainedWorkOutcome{result:reply.take().expect("recorded reply"),work:effect.performed_work()})},Ok(false)=>RetainedWorkPoll::Pending{work:effect.performed_work()},Err(error)=>RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(error.into()),work:effect.performed_work()})});
 authority.finish(&mut slot).expect("reply transferred");drop(authority.into_producer().ok().expect("finished action"));assert_ne!(bank.take_admitted(),Some(false));synchronous(poll)
}
#[test]
fn empty_array_denies_zero_work_then_publishes_the_real_zero_length_value(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️work/🥡️placement/🔣️.json")).unwrap();let mut bank=Wallet::from_profile(&law["stock"]);let mut effects=EffectBank::new(BankWallet::from_profile(&law["stock"]));let(mut cursor,heap)=observe(NativeArrayDefaultCursor::<u64,0>::new);assert_eq!(heap,(0,0));let mut checkpoint=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut checkpoint);let grant=bank.loan(1,4096);
 let(turn,heap)=observe(||fixture::receive(&mut control,grant,bank.work_loan(0),|native|synchronous(cursor.advance(native,4096,0,grant))));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert!(!cursor.output_ready());
 for _ in 0..10000{if cursor.output_ready(){break}let maximum=bank.work_remaining();let grant=bank.loan(1,4096);let(turn,heap)=observe(||fixture::receive(&mut control,grant,bank.work_loan(maximum),|native|synchronous(cursor.advance(native,4096,maximum,grant))));assert!(turn.work<=u128::from(maximum));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|error|error.retained_progress());bank.post(p,turn.work,grant,heap);turn.result.unwrap();}
 assert!(cursor.output_ready());let mut value=None;let quote=cursor.take_work_demand().unwrap();assert!(quote>0);let grant=RetainedCloneGrant{maximum_copy_bytes:0,..bank.loan(1,4096)};let denied=through_reply(&mut effects,grant,quote,&mut|effect,reply|cursor.take(&mut value,effect,reply));assert_eq!(denied.work,0);assert!(value.is_none());let grant=bank.loan(1,cursor.take_demand().unwrap().copy_bytes);let(turn,heap)=observe(||through_reply(&mut effects,grant,quote,&mut|effect,reply|cursor.take(&mut value,effect,reply)));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|error|error.retained_progress());bank.post(p,turn.work,grant,heap);turn.result.unwrap();assert_eq!(serde_json::to_value(value.take().unwrap()).unwrap(),law["emptyArray"]);cursor.begin_close();
 for _ in 0..10000{if cursor.terminal_is_empty(){break}let quote=cursor.close_work_demand(4096).unwrap();let grant=bank.loan(1,4096);let((poll,actual),heap)=observe(||effects.run(grant,quote,|effect|cursor.close_step(effect)));assert_ne!(effects.take_admitted(),Some(false));let turn=synchronous_close(poll);if let Some(bytes)=actual{assert_eq!(bytes,heap.0)}else{assert_eq!(heap.0,0)}let p=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());bank.post(p,turn.work,grant,heap);turn.result.unwrap();}
 assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1,(0,0));
}
fn synchronous_close(poll:RetainedWorkPoll<RetainedCloneStep,semio_framework_value_testing_admission::OriginalRetirementFailure>)->RetainedWorkOutcome<RetainedCloneStep,semio_framework_value_testing_admission::OriginalRetirementFailure>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("synchronous default close stayed pending")}}
